import Uint64 = require( '@stdlib/number/uint64/ctor' );
import sub = require( './index' );


// TESTS //

// The function returns a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	sub( a, a ); // $ExpectType Uint64
}

// The compiler throws an error if the function is provided a first argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	sub( true, a ); // $ExpectError
	sub( false, a ); // $ExpectError
	sub( null, a ); // $ExpectError
	sub( undefined, a ); // $ExpectError
	sub( '5', a ); // $ExpectError
	sub( [], a ); // $ExpectError
	sub( {}, a ); // $ExpectError
	sub( ( x: number ): number => x, a ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 5 );

	sub( a, true ); // $ExpectError
	sub( a, false ); // $ExpectError
	sub( a, null ); // $ExpectError
	sub( a, undefined ); // $ExpectError
	sub( a, '5' ); // $ExpectError
	sub( a, [] ); // $ExpectError
	sub( a, {} ); // $ExpectError
	sub( a, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const a = new Uint64( 5 );

	sub(); // $ExpectError
	sub( a ); // $ExpectError
	sub( a, a, a ); // $ExpectError
}

// Attached to main export is an `assign` method which returns a collection...
{
	const out = [ 0, 0 ];

	sub.assign( 0, 10, 0, 5, out, 1, 0 ); // $ExpectType number[]
}

// The compiler throws an error if the `assign` method is provided invalid arguments...
{
	const out = [ 0, 0 ];

	sub.assign( '5', 10, 0, 5, out, 1, 0 ); // $ExpectError
	sub.assign( 0, '10', 0, 5, out, 1, 0 ); // $ExpectError
	sub.assign( 0, 10, '0', 5, out, 1, 0 ); // $ExpectError
	sub.assign( 0, 10, 0, '5', out, 1, 0 ); // $ExpectError
	sub.assign( 0, 10, 0, 5, 123, 1, 0 ); // $ExpectError
	sub.assign( 0, 10, 0, 5, out, '1', 0 ); // $ExpectError
	sub.assign( 0, 10, 0, 5, out, 1, '0' ); // $ExpectError
}

// Attached to main export is a `strided` method which returns a collection...
{
	const a = [ 0, 10 ];
	const b = [ 0, 5 ];
	const out = [ 0, 0 ];

	sub.strided( a, 1, 0, b, 1, 0, out, 1, 0 ); // $ExpectType number[]
}

// The compiler throws an error if the `strided` method is provided invalid arguments...
{
	const a = [ 0, 10 ];
	const b = [ 0, 5 ];
	const out = [ 0, 0 ];

	sub.strided( 123, 1, 0, b, 1, 0, out, 1, 0 ); // $ExpectError
	sub.strided( a, '1', 0, b, 1, 0, out, 1, 0 ); // $ExpectError
	sub.strided( a, 1, '0', b, 1, 0, out, 1, 0 ); // $ExpectError
	sub.strided( a, 1, 0, 123, 1, 0, out, 1, 0 ); // $ExpectError
	sub.strided( a, 1, 0, b, '1', 0, out, 1, 0 ); // $ExpectError
	sub.strided( a, 1, 0, b, 1, '0', out, 1, 0 ); // $ExpectError
	sub.strided( a, 1, 0, b, 1, 0, 123, 1, 0 ); // $ExpectError
	sub.strided( a, 1, 0, b, 1, 0, out, '1', 0 ); // $ExpectError
	sub.strided( a, 1, 0, b, 1, 0, out, 1, '0' ); // $ExpectError
}
